<?php
namespace Tests\Feature;
use App\Domain\AI\Actions\{ActionRegistry};use App\Domain\AI\Actions\Contracts\ActionHandler;use App\Domain\AI\Actions\Data\{ActionDefinition,ActionExecutionContext,ActionRequestData,ActionResultData};use App\Domain\AI\Actions\Enums\{ActionConfirmationPolicy,ActionEffect,ActionRunStatus};use App\Domain\AI\Actions\Models\ActionRun;use App\Domain\AI\Actions\Services\ActionExecutor;use App\Domain\AI\Agents\Models\{AgentContractVersion,AgentVersion};use App\Domain\AI\Conversations\Models\{Conversation,ConversationMessage};use App\Domain\AI\Runtime\Models\RuntimeRun;use App\Domain\Network\Tenancy\Models\Tenant;use App\Domain\Network\Tenancy\TenantContext;use Illuminate\Database\QueryException;use Illuminate\Database\Schema\Blueprint;use Illuminate\Support\Facades\{DB,Schema};use Tests\TestCase;
final class AiActionFoundationTest extends TestCase
{
 protected function setUp():void{parent::setUp();config(['database.default'=>'sqlite','database.connections.sqlite.database'=>':memory:','app.key'=>'base64:'.base64_encode(str_repeat('a',32))]);$this->schema();}
 public function test_registry_definition_schema_and_structured_request_are_fail_closed():void{$handler=$this->handler();$registry=new ActionRegistry;$definition=$this->definition($handler);$registry->register($definition);$this->assertSame($definition,$registry->find('lookup_status'));$this->assertNull($registry->find('destroy_everything'));$this->expectException(\InvalidArgumentException::class);new ActionDefinition('App\\Danger','Danger','Danger', $this->inputSchema(),$this->outputSchema(),ActionEffect::Read,ActionConfirmationPolicy::None,$handler);}
 public function test_real_migration_is_reversible():void{$m=require base_path('database/migrations/2026_08_31_100000_create_ai_action_runs.php');$this->assertNotEmpty(DB::select("PRAGMA foreign_key_list('ai_action_runs')"));$m->down();$this->assertFalse(Schema::hasTable('ai_action_runs'));$m->up();$this->assertTrue(Schema::hasTable('ai_action_runs'));}
 public function test_migration_constraints_encryption_idempotency_and_read_execution():void{[$conversation,$message,$runtime]=$this->aggregate();$handler=$this->handler();app(ActionRegistry::class)->register($this->definition($handler));$executor=app(ActionExecutor::class);$action=$executor->reserve($conversation,$message,$runtime,new ActionRequestData('lookup_status',['reference'=>'ABC-123']));$same=$executor->reserve($conversation,$message,$runtime,new ActionRequestData('lookup_status',['reference'=>'ABC-123']));$this->assertSame($action->id,$same->id);$this->assertStringNotContainsString('ABC-123',(string)DB::table('ai_action_runs')->where('id',$action->id)->value('input'));$done=$executor->execute($action);$this->assertSame(ActionRunStatus::Succeeded,$done->status);$this->assertSame(['status'=>'ready','detail'=>'safe'],$done->output);$this->assertSame(1,$handler->calls);$this->assertSame(0,$handler->transactionLevel);$this->assertStringNotContainsString('ready',(string)DB::table('ai_action_runs')->where('id',$action->id)->value('output'));$other=DB::table('ai_conversations')->insertGetId(['uuid'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>1,'agent_id'=>1,'agent_version_id'=>1,'channel'=>'internal_test','status'=>'open','turn_in_progress'=>0,'next_sequence'=>1,'created_by_user_id'=>1,'created_at'=>now(),'updated_at'=>now()]);$copy=(array)DB::table('ai_action_runs')->where('id',$action->id)->first();$copy['id']=99;$copy['uuid']=(string)\Illuminate\Support\Str::uuid();$copy['conversation_id']=$other;$copy['idempotency_key']=str_repeat('b',64);try{DB::table('ai_action_runs')->insert($copy);$this->fail('Same-tenant mismatch must fail.');}catch(QueryException){$this->addToAssertionCount(1);}}
 public function test_write_waits_for_server_confirmation_and_double_confirmation_is_safe():void{[$conversation,$message,$runtime]=$this->aggregate();$handler=$this->handler();app(ActionRegistry::class)->register($this->definition($handler,ActionEffect::Write,ActionConfirmationPolicy::Required));$executor=app(ActionExecutor::class);$action=$executor->reserve($conversation,$message,$runtime,new ActionRequestData('lookup_status',['reference'=>'WRITE-1']));$this->assertSame(ActionRunStatus::AwaitingConfirmation,$action->status);$this->assertSame(0,$handler->calls);$done=$executor->confirm($action,1);$this->assertSame(ActionRunStatus::Succeeded,$done->status);$this->assertSame(1,$handler->calls);try{$executor->confirm($done,1);$this->fail('Double confirmation must fail.');}catch(\DomainException){$this->assertSame(1,$handler->calls);}}
 public function test_unknown_disallowed_invalid_input_and_invalid_output_fail_closed():void{[$conversation,$message,$runtime]=$this->aggregate();$executor=app(ActionExecutor::class);foreach([new ActionRequestData('unknown',['reference'=>'A'])]as$request)try{$executor->reserve($conversation,$message,$runtime,$request);$this->fail('Unknown Action must fail.');}catch(\DomainException){$this->assertSame(0,ActionRun::count());}$badHandler=new class implements ActionHandler{public int$calls=0;public function execute(ActionExecutionContext$c,array$a):ActionResultData{$this->calls++;return new ActionResultData(['wrong'=>'value']);}};app(ActionRegistry::class)->register($this->definition($badHandler));try{$executor->reserve($conversation,$message,$runtime,new ActionRequestData('lookup_status',['reference'=>['bad']]));$this->fail('Invalid input must fail.');}catch(\DomainException){$this->assertSame(0,$badHandler->calls);}$action=$executor->reserve($conversation,$message,$runtime,new ActionRequestData('lookup_status',['reference'=>'A']));$failed=$executor->execute($action);$this->assertSame(ActionRunStatus::Failed,$failed->status);$this->assertSame('action_output_invalid',$failed->safe_error_code);$this->assertNull($failed->output);}
 public function test_same_tenant_source_message_mismatch_is_rejected_by_guard():void{[$conversation,$message,$runtime]=$this->aggregate();$other=DB::table('ai_conversations')->insertGetId(['uuid'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>1,'agent_id'=>1,'agent_version_id'=>1,'channel'=>'internal_test','status'=>'open','turn_in_progress'=>0,'next_sequence'=>2,'created_by_user_id'=>1,'created_at'=>now(),'updated_at'=>now()]);DB::table('ai_conversation_messages')->insert(['id'=>2,'uuid'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>1,'conversation_id'=>$other,'sequence'=>1,'role'=>'user','status'=>'completed','content'=>'safe','needs_handoff'=>0,'completed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);app(ActionRegistry::class)->register($this->definition($this->handler()));try{app(ActionExecutor::class)->reserve($conversation,ConversationMessage::findOrFail(2),$runtime,new ActionRequestData('lookup_status',['reference'=>'A']));$this->fail('Mismatched source message must fail.');}catch(\DomainException){$this->assertSame(0,ActionRun::count());}}
 public function test_runtime_must_be_the_exact_run_linked_to_the_source_turn():void{[$conversation,$message,$runtime]=$this->aggregate();$otherConversation=DB::table('ai_conversations')->insertGetId(['uuid'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>1,'agent_id'=>1,'agent_version_id'=>1,'channel'=>'internal_test','status'=>'open','turn_in_progress'=>0,'next_sequence'=>2,'created_by_user_id'=>1,'created_at'=>now(),'updated_at'=>now()]);foreach([2,3]as$id)DB::table('ai_runtime_runs')->insert(['id'=>$id,'uuid'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>1,'agent_id'=>1,'agent_version_id'=>1,'purpose'=>'agent_draft_simulation','status'=>'completed','created_by_user_id'=>1,'started_at'=>now(),'completed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('ai_conversation_messages')->insert([['id'=>2,'uuid'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>1,'conversation_id'=>$otherConversation,'sequence'=>1,'role'=>'user','status'=>'completed','content'=>'other conversation','runtime_run_id'=>2,'needs_handoff'=>0,'completed_at'=>now(),'created_at'=>now(),'updated_at'=>now()],['id'=>3,'uuid'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>1,'conversation_id'=>$conversation->id,'sequence'=>2,'role'=>'user','status'=>'completed','content'=>'other turn','runtime_run_id'=>3,'needs_handoff'=>0,'completed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]]);$handler=$this->handler();app(ActionRegistry::class)->register($this->definition($handler));$executor=app(ActionExecutor::class);foreach([RuntimeRun::findOrFail(2),RuntimeRun::findOrFail(3)]as$incoherent){try{$executor->reserve($conversation,$message,$incoherent,new ActionRequestData('lookup_status',['reference'=>'WRONG-TURN']));$this->fail('A Runtime Run from another source turn must fail.');}catch(\DomainException){$this->assertSame(0,ActionRun::count());$this->assertSame(0,$handler->calls);}}$action=$executor->reserve($conversation,$message,$runtime,new ActionRequestData('lookup_status',['reference'=>'RIGHT-TURN']));$this->assertSame($runtime->id,$action->runtime_run_id);}
 public function test_write_action_cannot_await_confirmation_from_a_mismatched_runtime():void{[$conversation,$message]=$this->aggregate();DB::table('ai_runtime_runs')->insert(['id'=>2,'uuid'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>1,'agent_id'=>1,'agent_version_id'=>1,'purpose'=>'agent_draft_simulation','status'=>'completed','created_by_user_id'=>1,'started_at'=>now(),'completed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$handler=$this->handler();app(ActionRegistry::class)->register($this->definition($handler,ActionEffect::Write,ActionConfirmationPolicy::Required));try{app(ActionExecutor::class)->reserve($conversation,$message,RuntimeRun::findOrFail(2),new ActionRequestData('lookup_status',['reference'=>'WRITE-WRONG-TURN']));$this->fail('A mismatched WRITE Action must fail before reservation.');}catch(\DomainException){$this->assertSame(0,ActionRun::count());$this->assertSame(0,$handler->calls);}}
 public function test_execution_claim_prevents_duplicate_handler_calls():void{[$conversation,$message,$runtime]=$this->aggregate();$handler=$this->handler();app(ActionRegistry::class)->register($this->definition($handler));$executor=app(ActionExecutor::class);$action=$executor->reserve($conversation,$message,$runtime,new ActionRequestData('lookup_status',['reference'=>'RACE']));$duplicate=$executor->reserve($conversation,$message,$runtime,new ActionRequestData('lookup_status',['reference'=>'RACE']));$executor->execute($action);try{$executor->execute($duplicate);$this->fail('Duplicate execution must fail.');}catch(\DomainException){$this->assertSame(1,$handler->calls);}}
 private function handler():ActionHandler{return new class implements ActionHandler{public int$calls=0;public int$transactionLevel=-1;public function execute(ActionExecutionContext$context,array$arguments):ActionResultData{$this->calls++;$this->transactionLevel=DB::transactionLevel();return new ActionResultData(['status'=>'ready','detail'=>'safe']);}};}
 private function definition(ActionHandler$handler,ActionEffect$effect=ActionEffect::Read,ActionConfirmationPolicy$confirmation=ActionConfirmationPolicy::None):ActionDefinition{return new ActionDefinition('lookup_status','Consultar estado','Consulta segura',$this->inputSchema(),$this->outputSchema(),$effect,$confirmation,$handler);}private function inputSchema():array{return['type'=>'object','additionalProperties'=>false,'required'=>['reference'],'properties'=>['reference'=>['type'=>'string']]];}private function outputSchema():array{return['type'=>'object','additionalProperties'=>false,'required'=>['status','detail'],'properties'=>['status'=>['type'=>'string'],'detail'=>['type'=>'string']]];}
 private function aggregate():array{DB::table('users')->insert(['id'=>1,'name'=>'Owner','email'=>'owner@test','password'=>'x','empresa_id'=>1,'created_at'=>now(),'updated_at'=>now()]);DB::table('network_tenants')->insert(['id'=>1,'uuid'=>(string)\Illuminate\Support\Str::uuid(),'name'=>'Tenant','slug'=>'tenant','status'=>'active','created_at'=>now(),'updated_at'=>now()]);app(TenantContext::class)->set(Tenant::findOrFail(1));DB::table('ai_agents')->insert(['id'=>1,'tenant_id'=>1,'code'=>'A','name'=>'Agent','type'=>'sales','status'=>'draft','created_by_user_id'=>1,'created_at'=>now(),'updated_at'=>now()]);DB::table('ai_agent_contracts')->insert(['id'=>1,'tenant_id'=>1,'agent_id'=>1,'status'=>'draft','created_by_user_id'=>1,'created_at'=>now(),'updated_at'=>now()]);DB::table('ai_agent_contract_versions')->insert(['id'=>1,'tenant_id'=>1,'agent_contract_id'=>1,'version_number'=>1,'status'=>'draft','job_to_be_done'=>'Help','allowed_actions'=>json_encode(['lookup_status']),'created_by_user_id'=>1,'created_at'=>now(),'updated_at'=>now()]);DB::table('ai_agent_versions')->insert(['id'=>1,'tenant_id'=>1,'agent_id'=>1,'agent_contract_version_id'=>1,'version_number'=>1,'status'=>'draft','schema_version'=>'1','configuration'=>'{}','created_by_user_id'=>1,'created_at'=>now(),'updated_at'=>now()]);DB::table('ai_runtime_runs')->insert(['id'=>1,'uuid'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>1,'agent_id'=>1,'agent_version_id'=>1,'purpose'=>'agent_draft_simulation','status'=>'completed','created_by_user_id'=>1,'started_at'=>now(),'completed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('ai_conversations')->insert(['id'=>1,'uuid'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>1,'agent_id'=>1,'agent_version_id'=>1,'channel'=>'internal_test','status'=>'open','turn_in_progress'=>0,'next_sequence'=>2,'created_by_user_id'=>1,'created_at'=>now(),'updated_at'=>now()]);DB::table('ai_conversation_messages')->insert(['id'=>1,'uuid'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>1,'conversation_id'=>1,'sequence'=>1,'role'=>'user','status'=>'completed','content'=>'encrypted-user','runtime_run_id'=>1,'needs_handoff'=>0,'completed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return[Conversation::findOrFail(1),ConversationMessage::findOrFail(1),RuntimeRun::findOrFail(1)];}
 private function schema():void{DB::statement('PRAGMA foreign_keys=ON');Schema::create('users',function(Blueprint$t){$t->id();$t->string('name');$t->string('email');$t->string('password');$t->unsignedBigInteger('empresa_id');$t->timestamps();});Schema::create('network_tenants',function(Blueprint$t){$t->id();$t->uuid('uuid');$t->string('name');$t->string('slug');$t->string('status');$t->timestamps();});Schema::create('ai_agents',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->string('code');$t->string('name');$t->string('type');$t->string('status');$t->unsignedBigInteger('created_by_user_id');$t->timestamps();$t->unique(['tenant_id','id']);});Schema::create('ai_agent_contracts',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('agent_id');$t->string('status');$t->unsignedBigInteger('created_by_user_id');$t->timestamps();$t->unique(['tenant_id','id']);});Schema::create('ai_agent_contract_versions',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('agent_contract_id');$t->unsignedInteger('version_number');$t->string('status');$t->text('job_to_be_done');$t->json('allowed_actions');$t->unsignedBigInteger('created_by_user_id');$t->timestamps();$t->unique(['tenant_id','id']);});Schema::create('ai_agent_versions',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('agent_id');$t->unsignedBigInteger('agent_contract_version_id');$t->unsignedInteger('version_number');$t->string('status');$t->string('schema_version');$t->json('configuration');$t->unsignedBigInteger('created_by_user_id');$t->timestamps();$t->unique(['tenant_id','id']);$t->unique(['tenant_id','agent_id','id']);});Schema::create('ai_runtime_runs',function(Blueprint$t){$t->id();$t->uuid('uuid');$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('agent_id');$t->unsignedBigInteger('agent_version_id');$t->string('purpose');$t->string('status');$t->unsignedBigInteger('created_by_user_id');$t->timestamp('started_at');$t->timestamp('completed_at')->nullable();$t->timestamps();$t->unique(['tenant_id','id']);});Schema::create('ai_conversations',function(Blueprint$t){$t->id();$t->uuid('uuid');$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('agent_id');$t->unsignedBigInteger('agent_version_id');$t->string('channel');$t->string('status');$t->boolean('turn_in_progress');$t->unsignedInteger('next_sequence');$t->unsignedBigInteger('created_by_user_id');$t->timestamps();$t->unique(['tenant_id','id']);$t->unique(['tenant_id','id','agent_id','agent_version_id']);});Schema::create('ai_conversation_messages',function(Blueprint$t){$t->id();$t->uuid('uuid');$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('conversation_id');$t->unsignedInteger('sequence');$t->string('role');$t->string('status');$t->text('content')->nullable();$t->unsignedBigInteger('runtime_run_id')->nullable();$t->boolean('needs_handoff');$t->timestamp('completed_at')->nullable();$t->timestamps();$t->unique(['tenant_id','id']);});(require base_path('database/migrations/2026_08_31_100000_create_ai_action_runs.php'))->up();}
